import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

const UPLOADS = [
  { kind: "w9", file: "w9.txt" },
  { kind: "insurance_certificate", file: "insurance_certificate.txt" },
  { kind: "contract", file: "contract.txt" },
] as const;

test("documents cannot be added to a vendor under review", { tag: "@DOC-06" }, async ({ apiAs }) => {
  // Arrange: a draft vendor with all three documents extracted, then submitted for review
  const member = await apiAs("member");
  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("DOC-06 Vendor"), category: "logistics", contact_email: "ops@doc06.example" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = await created.json();

  for (const upload of UPLOADS) {
    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: upload.kind,
        file: {
          name: upload.file,
          mimeType: "text/plain",
          buffer: readFileSync(sample(upload.file)),
        },
      },
    });
    expect(res.status(), await res.text()).toBe(201);
  }

  // Wait for background extraction of every document before submitting
  await expect
    .poll(async () => {
      const list = await member.get(`/api/vendors/${vendor.id}/documents`);
      const docs = (await list.json()) as { status: string }[];
      return docs.length === 3 && docs.every((d) => d.status === "extracted");
    }, { timeout: 30_000 })
    .toBe(true);

  const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);
  expect((await submitted.json()).status, await submitted.text()).toBe("in_review");

  // Act: try to add another document while the vendor is in review
  const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: {
        name: "w9.txt",
        mimeType: "text/plain",
        buffer: readFileSync(sample("w9.txt")),
      },
    },
  });

  // Assert
  const body = await res.text();
  expect(res.status(), body).toBe(409);
  expect(JSON.parse(body).error.code, body).toBe("vendor_locked");
});
